    boolean[][] visited = new boolean[n][n];

    // Initialize a queue to perform BFS
    Queue<Integer> queue = new LinkedList<>();

    // Mark the starting n-tersection as visited and add it to the queue
    visited[start[0]][start[1]] = true;
    queue.add(start[0] * n + start[1]);

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the next n-tersection from the queue
        int x = queue.peek() / n;
        int y = queue.peek() % n;
        queue.remove();

        // If we have reached the ending n-tersection, return "can be travelled"
        if (x == end[0] && y == end[1]) {
            return "can be travelled";
        }

        // Check if the n-tersection has any paths to unvisited neighbors
        for (int i = 0; i < paths.length; i++) {
            int adjacentRow = x + paths[i][0];
            int adjacentCol = y + paths[i][1];

            // If the adjacent n-tersection is within the n-teresting space and has not been visited
            if (adjacentRow >= 0 && adjacentRow < n && adjacentCol >= 0 && adjacentCol < n
                    && !visited[adjacentRow][adjacentCol]) {
                // Mark the adjacent n-tersection as visited and add it to the queue
                visited[adjacentRow][adjacentCol] = true;
                queue.add(adjacentRow * n + adjacentCol);
            }
        }
    }

    // If we have visited all the n-tersections and have not reached the ending n-tersection, return "cannot be travelled"
    return "cannot be travelled";
