public static String convertDatesToWeekdays(String date) {
    // Check if input date is valid
    if (!isValidDate(date)) {
        throw new IllegalArgumentException("Invalid date: " + date);
    }

    // Parse input date into individual components
    String[] dateComponents = date.split(" ");
    int month = Integer.parseInt(dateComponents[0]);
    int day = Integer.parseInt(dateComponents[1]);
    int year = Integer.parseInt(dateComponents[2]);

    // Check if date is a leap year
    boolean isLeapYear = (year % 4 == 0 && (year % 100 != 0 || year % 400 == 0));

    // Get the weekday of the input date
    int weekday = getWeekday(month, day, year, isLeapYear);

    // Return the string representation of the weekday
    return weekdays[weekday];
}

