 * @param day the day of the date
 * @param year the year of the date
 * @param isLeapYear true if the date is in a leap year, false otherwise
 * @return the weekday of the date
 */
private static int getWeekday(int month, int day, int year, boolean isLeapYear) {
    int weekday = 0;
    switch (month) {
        case 1:
            weekday = day;
            break;
        case 2:
            weekday = day + 31;
            break;
        case 3:
            weekday = day + 59;
            break;
        case 4:
            weekday = day + 90;
