int bfs(Graph graph, int start, int end, HashMap<Integer, Integer> parentNodeMap) {
    // Create a queue to hold the nodes to visit
    LinkedList<Integer> queue = new LinkedList<>();
    // Add the start node to the queue
    queue.add(start);
    // Initialize the shortest path to infinity
    int shortestPath = Integer.MAX_VALUE;
    // Loop through the queue and visit each node
    while (!queue.isEmpty()) {
        // Remove the first node from the queue
        int node = queue.remove();
        // If the node is the end node, update the shortest path and return
        if (node == end) {
            shortestPath = Math.min(shortestPath, parentNodeMap.get(node));
            return shortestPath;
        }
        // Add the neighbors of the current node to the queue
        for (Integer neighbor : graph.getNeighbors(node)) {
            if (parentNodeMap.get(neighbor) < shortestPath) {
                // Update the shortest path and the map
                shortestPath = Math.min(shortestPath, parentNodeMap.get(neighbor));
                parentNodeMap.put(neighbor, shortestPath);
                // Add the new node to the queue
                queue.add(neighbor);
            }
        }
    }
    // Return the shortest path from node 0 to the end node
    return shortestPath;
}
