/**
 * Recursive method to calculate the minimum number of perfect square numbers that sum up to a given integer.
 *
 * @param n The remaining number to sum up to n.
 * @param currentSum The current sum of perfect square numbers.
 * @param minSum The minimum sum of perfect square numbers.
 * @return The minimum number of perfect square numbers.
 */
private static int getMinPerfectSquareSum(int n, int currentSum, int minSum) {
    if (n == 0) {
        return minSum;
    }
    if (n < 0) {
        return -1;
    }
    int perfectSquare = getPerfectSquare(n);
    if (perfectSquare == -1) {
        return -1;
    }
    return Math.min(getMinPerfectSquareSum(n - perfectSquare, currentSum + 1, minSum),
            getMinPerfectSquareSum(perfectSquare, currentSum, minSum + 1));
}

